function moduleOf(key2) {
  return key2.split(".")[0] ?? key2;
}
function permissionName(key2) {
  const [, action] = key2.split(".");
  return `${moduleOf(key2)}: ${action ?? key2}`.replace(/\b\w/g, (c) => c.toUpperCase());
}
